// ELEMENTS:
// 1. Fundo navy
// 2. Foto grande (src) e foto menor (src2) sobrepostas, como numa revista, a afastarem-se devagar
// 3. Moldura azul IAD na foto menor
// 4. Label + legenda em serifa branca
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { MediaImg as Img } from "../media";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const NAVY_RGB = "0,31,68";
const CYAN = "#DE212B";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.24) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const DuoSobreposto: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const src2 = String(p.src2 ?? "");
  const label = String(p.label ?? "").trim();
  const caption = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.8): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay, 0.7);
    return { opacity: t, transform: `translateY(${(1 - t) * 20 * u}px)` };
  };
  // Slow parallax: the two photos drift apart, in opposite directions.
  const k = interpolate(f, [0, T], [0, 1], { ...clamp, easing: Easing.inOut(Easing.sin) });

  // Big photo up-left, smaller one overlapping down-right; in landscape the text gets its own column on the right.
  const big = land
    ? { left: W * 0.05, top: H * 0.1, width: W * 0.42, height: H * 0.68 }
    : { left: W * 0.07, top: H * 0.1, width: W * 0.7, height: H * 0.44 };
  const small = land
    ? { left: W * 0.34, top: H * 0.4, width: W * 0.26, height: H * 0.46 }
    : { left: W * 0.4, top: H * 0.42, width: W * 0.53, height: H * 0.3 };
  const a = show(0, 0.9);
  const b = show(0.35, 0.9);
  const line = show(0.8, 0.8);

  const photo = (s: string, scale: number) =>
    s ? <Img src={s} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)", transform: `scale(${scale})` }} /> : null;

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", backgroundColor: NAVY, overflow: "hidden" }}>
      <div style={{ position: "absolute", ...big, overflow: "hidden", opacity: a, transform: `translate(${(-k * 14 - (1 - a) * 40) * u}px, ${-k * 10 * u}px)` }}>
        {photo(src, 1.1 - 0.06 * k)}
      </div>
      <div
        style={{
          position: "absolute",
          ...small,
          opacity: b,
          transform: `translate(${(k * 14 + (1 - b) * 40) * u}px, ${(k * 10 + (1 - b) * 30) * u}px)`,
          boxShadow: "0 30px 80px rgba(0,0,0,0.45)",
        }}
      >
        <div style={{ position: "absolute", inset: -16 * u, border: `${2 * u}px solid rgba(255,255,255,0.45)`, clipPath: `inset(0 0 ${(1 - line) * 100}% 0)` }} />
        <div style={{ position: "absolute", inset: 0, overflow: "hidden" }}>{photo(src2, 1.02 + 0.06 * k)}</div>
      </div>
      <div
        style={{
          position: "absolute",
          left: land ? W * 0.66 : 80 * u,
          right: land ? W * 0.05 : 80 * u,
          bottom: land ? H * 0.38 : (format === "portrait" ? 190 : 60) * u,
          display: "flex",
          flexDirection: "column",
          gap: 20 * u,
        }}
      >
        {label ? (
          <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 36 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.9) }}>{label}</div>
        ) : null}
        {caption ? (
          <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 92 * u, lineHeight: 1.05, color: WHITE, ...rise(1.0) }}>{caption}</div>
        ) : null}
      </div>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default DuoSobreposto;
